PREFIX : <http://sdw.example/ocsf#>
SELECT ?stage ?startTime ?endTime ?host
WHERE {
  ?stage a :Session ;
         :startTime ?startTime ;
         :endTime ?endTime ;
         :host ?host .
}
ORDER BY ?startTime

PREFIX :    <http://sdw.example/ocsf#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?event ?stage ?eventUid ?startTime WHERE {
  {
    ?event a :Process ;
           :eventUid ?eventUid .
    OPTIONAL { ?event :cmdLine ?cmdLine }
    BIND("process" AS ?stage)
  }
  UNION
  {
    ?event a :ApiEvent ;
           :eventUid ?eventUid .
    OPTIONAL { ?event :operation ?operation }
    OPTIONAL { ?event :mfaPresent ?mfaPresent }
    OPTIONAL { ?event :actor ?actor }
    BIND("api" AS ?stage)
  }
  UNION
  {
    ?event a :Session ;
           :eventUid ?eventUid .
    OPTIONAL { ?event :startTime ?startTime }
    OPTIONAL { ?event :endTime ?endTime }
    BIND("session" AS ?stage)
  }
}
ORDER BY ?startTime ?eventUid

PREFIX : <http://sdw.example/ocsf#>
SELECT ?eventUid ?type ?cmdLine ?operation ?mfaPresent ?host ?startTime WHERE {
  {
    ?e a :Process ;
       :eventUid ?eventUid ;
       :cmdLine ?cmdLine .
    OPTIONAL { ?e :host ?host . }
    BIND("Process" AS ?type)
  }
  UNION
  {
    ?e a :ApiEvent ;
       :eventUid ?eventUid ;
       :operation ?operation .
    OPTIONAL { ?e :mfaPresent ?mfaPresent . }
    BIND("ApiEvent" AS ?type)
  }
  UNION
  {
    ?e a :Session ;
       :eventUid ?eventUid ;
       :startTime ?startTime .
    OPTIONAL { ?e :host ?host . }
    BIND("Session" AS ?type)
  }
}
ORDER BY ?startTime ?eventUid

PREFIX : <http://sdw.example/ocsf#>
SELECT ?event ?startTime ?endTime ?host ?cmdLine ?operation ?mfaPresent ?actor WHERE {
  ?event :startTime ?startTime .
  OPTIONAL { ?event :endTime ?endTime }
  OPTIONAL { ?event :host ?host }
  OPTIONAL { ?event :cmdLine ?cmdLine }
  OPTIONAL { ?event :operation ?operation }
  OPTIONAL { ?event :mfaPresent ?mfaPresent }
  OPTIONAL { ?event :actor ?actor }
}
ORDER BY ?startTime

PREFIX :    <http://sdw.example/ocsf#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?eventUid ?stageType ?detail ?orderKey WHERE {
  {
    ?e a :Process ;
       :eventUid ?eventUid ;
       :cmdLine ?detail .
    BIND("Process" AS ?stageType)
    BIND(?eventUid AS ?orderKey)
  }
  UNION
  {
    ?e a :ApiEvent ;
       :eventUid ?eventUid ;
       :operation ?detail .
    BIND("ApiEvent" AS ?stageType)
    BIND(?eventUid AS ?orderKey)
  }
  UNION
  {
    ?e a :Session ;
       :eventUid ?eventUid ;
       :startTime ?detail .
    BIND("Session" AS ?stageType)
    BIND(?eventUid AS ?orderKey)
  }
}
ORDER BY ASC(?orderKey)

PREFIX : <http://sdw.example/ocsf#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?eventUid ?stageType ?cmdLine ?operation ?mfaPresent ?actor ?host ?startTime ?endTime WHERE {
  {
    ?e a :Process ; :eventUid ?eventUid .
    BIND("Process" AS ?stageType)
    OPTIONAL { ?e :cmdLine ?cmdLine }
    OPTIONAL { ?e :host ?host }
  }
  UNION
  {
    ?e a :ApiEvent ; :eventUid ?eventUid .
    BIND("ApiEvent" AS ?stageType)
    OPTIONAL { ?e :operation ?operation }
    OPTIONAL { ?e :mfaPresent ?mfaPresent }
    OPTIONAL { ?e :actor ?actor }
  }
  UNION
  {
    ?e a :Session ; :eventUid ?eventUid .
    BIND("Session" AS ?stageType)
    OPTIONAL { ?e :host ?host }
    OPTIONAL { ?e :startTime ?startTime }
    OPTIONAL { ?e :endTime ?endTime }
  }
}
ORDER BY ?startTime ?eventUid

PREFIX : <http://sdw.example/ocsf#>
SELECT ?eventUid ?stage ?detail ?startTime WHERE {
  {
    ?e a :Process ;
       :eventUid ?eventUid ;
       :cmdLine ?detail .
    BIND("Process" AS ?stage)
    OPTIONAL { ?e :startTime ?startTime }
  }
  UNION
  {
    ?e a :ApiEvent ;
       :eventUid ?eventUid ;
       :operation ?detail .
    BIND("ApiEvent" AS ?stage)
    OPTIONAL { ?e :startTime ?startTime }
  }
  UNION
  {
    ?e a :Session ;
       :eventUid ?eventUid ;
       :startTime ?startTime .
    OPTIONAL { ?e :host ?detail }
    BIND("Session" AS ?stage)
  }
