ORDER BY ASC(?startTime) ?eventUid

PREFIX : <http://sdw.example/ocsf#>
SELECT ?startTime ?eventUid ?stage ?cmdLine ?operation ?mfaPresent ?actor ?host ?endTime
WHERE {
  {
    ?e a :Session ;
       :eventUid ?eventUid ;
       :startTime ?startTime ;
       :endTime ?endTime ;
       :host ?host .
    BIND("Session" AS ?stage)
  }
  UNION
  {
    ?e a :Process ;
       :eventUid ?eventUid ;
       :cmdLine ?cmdLine ;
       :host ?host .
    BIND("Process" AS ?stage)
  }
  UNION
  {
    ?e a :ApiEvent ;
       :eventUid ?eventUid ;
       :operation ?operation ;
       :mfaPresent ?mfaPresent ;
       :actor ?actor .
    BIND("ApiEvent" AS ?stage)
  }
}
ORDER BY ?startTime ?eventUid

